// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.cognitive.decisionimport com.roshan.persona.cognitive.model.DecisionOptionimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContext/** * NOUS — Risk Assessor (Module 7 v2 — Step 7.5). * * Assesses risks for each decision option — what could go wrong? * * ## What it does * * Given a list of options, generates a risk assessment: *  - List of risks per option (e.g., "expensive", "locked ecosystem"). *  - Risk level: LOW / MEDIUM / HIGH. *  - Mitigation suggestions (optional). * * For v1, risks are extracted heuristically based on option names + common * risk patterns. v2+ uses LLM for novel risk assessment. * * @see <a href="docs/strategy/module-7-cognitive-strategy-v2.md">§DecisionMaker</a> */class RiskAssessor(    private val dispatcher: CoroutineDispatcher,) {    /**     * Assess risks for each [option].     *     * @param options the options to assess.     * @return map of option name → [RiskAssessment].     */    suspend fun assessRisks(options: List<DecisionOption>): Map<String, RiskAssessment> = withContext(dispatcher) {        options.associate { option ->            option.name to assessSingle(option)        }    }    /**     * Assess risks for a single option.     *     * Uses heuristic risk patterns:     *  - Low overall score → "May not meet your needs"     *  - High price criterion → "Expensive"     *  - Low scores across criteria → "Underperforming"     */    private fun assessSingle(option: DecisionOption): RiskAssessment {        val risks = mutableListOf<String>()        // Low overall score.        if (option.overallScore < 0.4f) {            risks.add("May not meet your needs — low overall quality")        }        // Specific criterion risks.        option.scores.forEach { (criterion, score) ->            if (criterion.contains("price") && score > 0.7f) {                risks.add("Expensive — high cost relative to alternatives")            }            if (criterion.contains("risk") && score > 0.6f) {                risks.add("Higher risk profile")            }            if (criterion.contains("battery") && score < 0.3f) {                risks.add("Poor battery life")            }            if (criterion.contains("safety") && score < 0.4f) {                risks.add("Safety concerns")            }            if (criterion.contains("liquidity") && score < 0.3f) {                risks.add("Low liquidity — hard to withdraw")            }        }        // If no specific risks found, add generic.        if (risks.isEmpty()) {            risks.add("No significant risks identified")        }        val level = when {            option.overallScore < 0.3f -> RiskLevel.HIGH            option.overallScore < 0.5f -> RiskLevel.MEDIUM            else -> RiskLevel.LOW        }        return RiskAssessment(            risks = risks,            level = level,        )    }}// ──────────────────────────────────────────────────────────────────────────/** Risk assessment for one option. */data class RiskAssessment(    val risks: List<String>,    val level: RiskLevel,)/** Risk severity level. */enum class RiskLevel(val displayLabel: String) {    LOW("Low Risk"),    MEDIUM("Medium Risk"),    HIGH("High Risk"),}// ═══════════════════════════════════════════════════════════════════════════/** * NOUS — Preference Aligner (Module 7 v2 — Step 7.5). * * Aligns decision recommendations with user preferences recalled from * Module 3 (Memory). * * ## What it does * * 1. Recalls user preferences from Memory ("user prefers budget-conscious *    options", "user values camera quality"). * 2. Adjusts criterion weights based on preferences. * 3. Re-scores options with adjusted weights. * 4. Returns the preferences that were applied (for transparency). * * ## Example * * User asks "iPhone vs Android". Memory recalls: *  - "user prefers budget-conscious options" → increase price weight *  - "user values customization" → increase customization weight * * After alignment: *  - Android scores higher (better price + customization) *  - iPhone scores lower (expensive + locked) *  - Recommendation shifts from iPhone → Android * * For v1, preferences are passed in directly. v2+ recalls from Memory. * * @see <a href="docs/strategy/module-7-cognitive-strategy-v2.md">§DecisionMaker</a> */class PreferenceAligner(    private val dispatcher: CoroutineDispatcher,) {    /**     * Align criterion weights with user preferences.     *     * @param criteria the original criteria.     * @param userPreferences list of preference keys ("budget-conscious", "camera-focused").     * @return adjusted criteria + list of applied preferences.     */    suspend fun align(        criteria: List<com.roshan.persona.cognitive.model.DecisionCriterion>,        userPreferences: List<String>,    ): PreferenceAlignmentResult = withContext(dispatcher) {        val adjusted = criteria.map { criterion ->            var newWeight = criterion.weight            val appliedPrefs = mutableListOf<String>()            for (pref in userPreferences) {                val lower = pref.lowercase()                when {                    lower.contains("budget") && criterion.name.contains("price") -> {                        newWeight = (newWeight * 1.5f).coerceAtMost(1f)                        appliedPrefs.add(pref)                    }                    lower.contains("camera") && criterion.name.contains("camera") -> {                        newWeight = (newWeight * 1.5f).coerceAtMost(1f)                        appliedPrefs.add(pref)                    }                    lower.contains("battery") && criterion.name.contains("battery") -> {                        newWeight = (newWeight * 1.4f).coerceAtMost(1f)                        appliedPrefs.add(pref)                    }                    lower.contains("safety") && criterion.name.contains("safety") -> {                        newWeight = (newWeight * 1.5f).coerceAtMost(1f)                        appliedPrefs.add(pref)                    }                    lower.contains("custom") && criterion.name.contains("custom") -> {                        newWeight = (newWeight * 1.5f).coerceAtMost(1f)                        appliedPrefs.add(pref)                    }                    lower.contains("quality") && criterion.name.contains("quality") -> {                        newWeight = (newWeight * 1.4f).coerceAtMost(1f)                        appliedPrefs.add(pref)                    }                }            }            criterion.copy(weight = newWeight)        }        val allApplied = userPreferences.filter { pref ->            adjusted.any { it.weight != criteria.find { c -> c.name == it.name }?.weight }        }        PreferenceAlignmentResult(            adjustedCriteria = adjusted,            appliedPreferences = allApplied,        )    }}/** Result of preference alignment. */data class PreferenceAlignmentResult(    val adjustedCriteria: List<com.roshan.persona.cognitive.model.DecisionCriterion>,    val appliedPreferences: List<String>,)